import {Component, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';
import {RouterModule, ActivatedRoute} from '@angular/router';
import {FormsModule} from '@angular/forms';
import {ProductService} from '../product.service';
import {Product} from '../models/product.model';
import {CartService} from '../cart.service';

@Component({
    selector: 'app-product-detail',
    standalone: true,
    imports: [CommonModule, RouterModule, FormsModule],
    templateUrl: './product-detail.component.html',
    styleUrl: './product-detail.component.css'
})
export class ProductDetailComponent implements OnInit {

    product: any = {
        id: 1,
        name: 'Loading...',
        brand: '',
        price: 0,
        originalPrice: 0,
        description: 'Loading product details...',
        image: '',
        category: 'Products',
        inStock: true,
        rating: 0,
        reviewCount: 0,
        features: []
    };    searchQuery: string = '';
    quantity: number = 1;
    isLoading: boolean = false;
    error: string | null = null;

    constructor(
        private route: ActivatedRoute,
        private productService: ProductService,
        private cartService: CartService
    ) {}

    ngOnInit(): void {
        // Get product ID from route parameters
        this.route.params.subscribe(params => {
            if (params['id']) {
                this.loadProduct(params['id']);
            } else {
                // Handle case where no ID is provided - try to get it from query params
                this.route.queryParams.subscribe(queryParams => {
                    if (queryParams['name']) {
                        this.loadProductByName(queryParams['name']);
                    }
                });
            }
        });
    }

    loadProduct(id: string): void {
        this.isLoading = true;
        this.productService.getProductById(Number(id)).subscribe({
            next: (product) => {
                this.processProduct(product);
                this.isLoading = false;
            },
            error: (err) => {
                console.error('Error loading product details:', err);
                this.error = 'Unable to load product. Please try again later.';
                this.isLoading = false;
            }
        });
    }

    loadProductByName(name: string): void {
        this.isLoading = true;
        this.productService.getProductByName(name).subscribe({
            next: (product) => {
                if (product) {
                    this.processProduct(product);
                } else {
                    this.error = 'Product not found';
                }
                this.isLoading = false;
            },
            error: (err) => {
                console.error('Error loading product by name:', err);
                this.error = 'Unable to load product. Please try again later.';
                this.isLoading = false;
            }
        });
    }
    
    // Process the product data from API to match our UI needs
    processProduct(product: Product): void {
        // Convert API product to UI format
        this.product = {
            id: 1, // API doesn't provide ID currently
            name: product.name,
            brand: product.brandName,
            price: this.extractPrice(product.price),
            originalPrice: 0, // API doesn't provide original price
            description: product.description,
            image: product.imageLink,
            category: 'Products', // Default category
            inStock: true, // Assume in stock
            rating: 4.5, // Default rating as API doesn't provide it
            reviewCount: 0, // Default as API doesn't provide it
            features: this.extractFeatures(product.description)
        };
    }
    
    // Extract price from string like "345,000₫" to number
    extractPrice(priceStr: string): number {
        // Remove non-numeric characters and convert to number
        const numericString = priceStr.replace(/[^0-9]/g, '');
        return parseFloat(numericString) / 1000; // Convert to appropriate format
    }
    
    // Extract features from description
    extractFeatures(description: string): string[] {
        // Simple extraction - split by sentences or look for bullet points
        const features = [];
        const sentences = description.split('.');
        
        // Take up to 5 sentences as features
        for (let i = 0; i < Math.min(5, sentences.length); i++) {
            const sentence = sentences[i].trim();
            if (sentence.length > 10) { // Only add non-empty sentences
                features.push(sentence);
            }
        }
        
        return features.length > 0 ? features : ['Detailed product description available'];
    }    onAddToCart(): void {
        // Create a product-like object that satisfies the cart service requirements
        const cartProduct = {
            name: this.product.name,
            brandName: this.product.brand,
            price: this.product.price.toString(),
            imageLink: this.product.image,
            detailLink: window.location.href,
            description: this.product.description,
            quantity: this.quantity
        };
        
        this.cartService.addToCart(cartProduct);
        console.log('Added to cart:', cartProduct);
    }

    onAddToWishlist(): void {
        console.log('Adding to wishlist:', this.product);
        // Wishlist functionality can be implemented later
    }

    onSearch(): void {
        if (this.searchQuery.trim()) {
            console.log('Searching for:', this.searchQuery);
            // Search functionality implementation
        }
    }

    incrementQuantity(): void {
        this.quantity++;
    }

    decrementQuantity(): void {
        if (this.quantity > 1) {
            this.quantity--;
        }
    }

    onQuantityChange(): void {
        if (this.quantity < 1) {
            this.quantity = 1;
        }
    }

    getDiscountPercentage(): number {
        if (this.product.originalPrice && this.product.price) {
            return Math.round(((this.product.originalPrice - this.product.price) / this.product.originalPrice) * 100);
        }
        return 0;
    }
}
